style.css:
body {
  background: url("https://images.unsplash.com/photo-1446776811953-b23d57bd21aa?auto=format&fit=crop&w=1920&q=80") no-repeat center center fixed !important;
  background-size: cover !important;
}

/* затемнение фона */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.6);
  z-index: -1;
}

/* синие рамки по краям экрана */
body::after {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  box-shadow: 0 0 25px 5px rgba(0, 153, 255, 0.6) inset;
  pointer-events: none;
  z-index: 9999;
}

/* подсветка блоков */
div, section, article, header, footer {
  border: 1px solid rgba(0, 153, 255, 0.4);
  border-radius: 10px;
  transition: 0.3s ease;
}

div:hover, section:hover, article:hover {
  box-shadow: 0 0 15px rgba(0, 153, 255, 0.7);
}
